<template>
  <div class="auth-page">
    <div class="auth-hero"><img src="/images/lingshan_3.jpeg" :alt="t('auth.scenicAlt')" /><div class="hero-overlay"/><div class="hero-content"><img src="/images/logo.png" class="hero-logo" alt="logo" /><h1>{{ t('auth.brand') }}</h1><p>{{ t('auth.subtitle') }}</p></div></div>
    <div class="auth-form-wrap"><div class="card auth-card">
      <div class="mode-toggle"><button :class="{active:mode==='login'}" @click="switchMode('login')">{{ t('auth.login') }}</button><button :class="{active:mode==='register'}" @click="switchMode('register')">{{ t('auth.register') }}</button></div>
      <h2 v-if="mode==='reset'">{{ t('auth.reset') }}</h2>
      <div class="input-row"><span>+86</span><input v-model="phone" type="tel" maxlength="11" :placeholder="t('auth.phone')" /></div>
      <div v-if="mode!=='login'" class="input-row verify"><input v-model="verifyCode" maxlength="6" :placeholder="t('auth.code')"/><button :disabled="phone.length!==11||countdown>0" @click="sendCode">{{ countdown>0?`${countdown}s`:codeSent?t('auth.resend'):t('auth.getCode') }}</button></div>
      <div class="input-row"><input v-model="password" :type="showPwd?'text':'password'" :placeholder="mode==='login'?t('auth.password'):mode==='reset'?t('auth.newPassword'):t('auth.setPassword')"/><button class="eye" @click="showPwd=!showPwd">{{ showPwd?'◉':'○' }}</button></div>
      <template v-if="mode==='register'"><div class="input-row"><input v-model="confirmPassword" type="password" :placeholder="t('auth.confirmPassword')"/></div><p v-if="confirmPassword&&confirmPassword!==password" class="error">{{ t('auth.passwordMismatch') }}</p></template>
      <div v-if="mode==='login'" class="forgot"><button @click="switchMode('reset')">{{ t('auth.forgot') }}</button></div>
      <div v-if="mode==='register'" class="terms"><button :class="{checked:agreeTerms}" @click="agreeTerms=!agreeTerms">✓</button><span>{{ t('auth.termsPrefix') }} <a>{{ t('auth.userAgreement') }}</a>{{ t('auth.and') }}<a>{{ t('auth.privacy') }}</a></span></div>
      <button v-if="isDesktop" class="submit desktop-login ready" :disabled="desktopLoading" @click="desktopLogin">{{ desktopLoading ? '正在进入…' : '一键本机体验' }}</button>
      <button class="submit" :class="{ready:canSubmit}" :disabled="!canSubmit" @click="handleSubmit">{{ mode==='login'?t('auth.submitLogin'):mode==='register'?t('auth.submitRegister'):t('auth.submitReset') }}</button>
      <button v-if="mode==='reset'" class="return-login" @click="switchMode('login')">{{ t('common.back') }}</button>
      <template v-else><div class="divider"><i/><span>{{ t('auth.other') }}</span><i/></div><div class="third"><button @click="thirdParty"><b>💬</b>{{ t('auth.wechat') }}</button><button @click="thirdParty"><b>📱</b>{{ t('auth.oneTap') }}</button></div></template>
    </div><p class="footer">{{ t('auth.footer') }}</p></div>
  </div>
</template>
<script setup lang="ts">
import { computed, onUnmounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { useI18n } from 'vue-i18n'
import { ElMessage } from 'element-plus'
const router=useRouter();const {t}=useI18n();const mode=ref<'login'|'register'|'reset'>('login');const phone=ref('');const password=ref('');const confirmPassword=ref('');const verifyCode=ref('');const codeSent=ref(false);const countdown=ref(0);const agreeTerms=ref(false);const showPwd=ref(false);const desktopLoading=ref(false);const isDesktop=window.lingguideDesktop?.runtime==='desktop';let timer:ReturnType<typeof setInterval>|null=null
const canSubmit=computed(()=>{if(!phone.value.trim()||!password.value.trim())return false;if(mode.value==='login')return true;if(!verifyCode.value.trim())return false;if(mode.value==='reset')return password.value.length>=6;return confirmPassword.value===password.value&&agreeTerms.value})
function switchMode(value:typeof mode.value){mode.value=value;password.value='';confirmPassword.value='';verifyCode.value=''}
async function sendCode(){if(phone.value.length!==11||countdown.value>0)return;try{const res=await fetch(`/api/auth/send-code?phone=${encodeURIComponent(phone.value)}`,{method:'POST'});if(!res.ok)throw new Error();const data=await res.json();ElMessage.success(data.code?t('auth.codeDev',{code:data.code}):t('auth.codeSent'));codeSent.value=true;countdown.value=60;timer=setInterval(()=>{countdown.value--;if(countdown.value<=0&&timer){clearInterval(timer);timer=null}},1000)}catch{ElMessage.warning(t('auth.codeFailed'))}}
async function handleSubmit(){if(!canSubmit.value)return;try{const endpoint=mode.value==='login'?'/api/auth/login':mode.value==='register'?'/api/auth/register':'/api/auth/reset-password';const body:Record<string,string>=mode.value==='reset'?{phone:phone.value.trim(),new_password:password.value,verify_code:verifyCode.value}:{phone:phone.value.trim(),password:password.value};if(mode.value==='register')body.verify_code=verifyCode.value;const res=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!res.ok){const error=await res.json().catch(()=>({}));throw new Error(error.detail||t('auth.requestFailed'))}if(mode.value==='reset'){ElMessage.success(t('auth.resetSuccess'));switchMode('login');return}const data=await res.json();saveSession(data);ElMessage.success(mode.value==='login'?t('auth.loginSuccess'):t('auth.registerSuccess'));router.replace({name:'home'})}catch(error:any){ElMessage.error(error.message||t('common.operationFailed'))}}
function saveSession(data:any){if(typeof data?.token!=='string'||!data.token)throw new Error(t('auth.requestFailed'));localStorage.setItem('lingguide_token',data.token);localStorage.setItem('lingguide_user',JSON.stringify(data.user||{}))}
async function desktopLogin(){if(desktopLoading.value)return;desktopLoading.value=true;try{const res=await fetch('/api/auth/desktop-login',{method:'POST'});if(!res.ok){const error=await res.json().catch(()=>({}));throw new Error(error.detail||t('auth.requestFailed'))}saveSession(await res.json());ElMessage.success('已进入本机体验');router.replace({name:'home'})}catch(error:any){ElMessage.error(error.message||t('common.operationFailed'))}finally{desktopLoading.value=false}}
function thirdParty(){ElMessage.info(t('auth.thirdPartyDeveloping'))}onUnmounted(()=>{if(timer)clearInterval(timer)})
</script>
<style scoped>
.auth-page{min-height:100vh;display:flex;flex-direction:column}.auth-hero{position:relative;height:260px;overflow:hidden}.auth-hero>img{width:100%;height:100%;object-fit:cover}.hero-overlay{position:absolute;inset:0;background:linear-gradient(to bottom,rgba(45,106,79,.4),rgba(45,106,79,.2),var(--color-bg-page))}.hero-content{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#fff}.hero-logo{width:72px;height:72px;border-radius:16px;object-fit:contain;background:rgba(255,255,255,.15);padding:4px}.hero-content h1{margin-top:14px;font-size:1.5rem}.hero-content p{margin-top:4px;font-size:.875rem;opacity:.85}.auth-form-wrap{flex:1;padding:0 20px 40px;margin-top:-24px;z-index:2}.auth-card{padding:24px}.mode-toggle{display:flex;padding:4px;margin-bottom:22px;border-radius:12px;background:var(--color-bg-muted)}.mode-toggle button{flex:1;padding:10px;border:0;border-radius:8px;background:none;color:var(--color-text-muted);font-weight:600;cursor:pointer}.mode-toggle .active{background:#fff;color:var(--color-primary)}h2{text-align:center;margin-bottom:18px;font-size:1.1rem}.input-row{position:relative;display:flex;align-items:center;gap:10px;margin-bottom:14px}.input-row>span{position:absolute;left:14px;color:var(--color-text-secondary);font-size:.8125rem}.input-row>span+input{padding-left:56px}.input-row input{width:100%;padding:14px;border:1px solid rgba(0,0,0,.04);border-radius:12px;background:var(--color-bg-input);outline:none;font:inherit}.verify input{flex:1}.verify>button{height:48px;padding:0 14px;border:0;border-radius:12px;background:var(--color-primary-bg);color:var(--color-primary);white-space:nowrap}.eye{position:absolute;right:14px;border:0;background:none;cursor:pointer}.error{margin:-8px 4px 8px;color:var(--color-error);font-size:10px}.forgot{text-align:right}.forgot button,.return-login{border:0;background:none;color:var(--color-primary);cursor:pointer}.terms{display:flex;gap:8px;align-items:flex-start;margin-top:16px;color:var(--color-text-muted);font-size:11px;line-height:1.6}.terms>button{width:18px;height:18px;border:1px solid rgba(0,0,0,.1);border-radius:4px;background:#fff;color:transparent}.terms>button.checked{background:var(--color-primary);color:#fff}.terms a{color:var(--color-primary)}.submit{width:100%;margin-top:22px;padding:14px;border:0;border-radius:12px;background:rgba(0,0,0,.06);color:var(--color-text-muted);font-weight:600}.submit.ready{background:var(--color-primary);color:#fff;cursor:pointer}.desktop-login{margin-top:0;margin-bottom:-8px;background:#1b4332}.return-login{width:100%;margin-top:14px}.divider{display:flex;align-items:center;gap:16px;margin:24px 0;color:var(--color-text-muted);font-size:11px}.divider i{flex:1;height:1px;background:rgba(0,0,0,.06)}.third{display:flex;justify-content:center;gap:36px}.third button{display:flex;flex-direction:column;gap:5px;border:0;background:none;color:var(--color-text-muted);font-size:10px;cursor:pointer}.third b{font-size:22px}.footer{text-align:center;margin-top:24px;color:var(--color-text-muted);font-size:10px}
</style>
